import collections
import re

def analyze_dream(dream_text):
    """
    Analyzes dream text to extract keyword frequencies and calculate a sentiment score.
    """
    if not dream_text:
        return {"frequency": [], "sentiment_score": 0}

    words = re.findall(r'\w+', dream_text.lower())
    frequency = collections.Counter(words)

    positive_keywords = {'fly', 'happy', 'light', 'peace', 'soar', 'bright'}
    negative_keywords = {'fall', 'chase', 'dark', 'fear', 'lost', 'trap'}

    sentiment_score = 0
    for word in words:
        if word in positive_keywords:
            sentiment_score += 1
        elif word in negative_keywords:
            sentiment_score -= 1

    return {
        "frequency": frequency.most_common(5),
        "sentiment_score": sentiment_score
    }

if __name__ == '__main__':
    sample_dream = "I was flying in the light and felt happy, but then I started to fall in the dark."
    results = analyze_dream(sample_dream)
    print(f"Analysis Results: {results}")

